export type Problem = {
  /**
   * Stable application error code used by clients
   *
   * @format uri-reference
   * @example not_found
   */
  type: string;
  /**
   * HTTP status reason phrase
   *
   * @example Not Found
   */
  title: string;
  /**
   * HTTP status code for this problem occurrence
   *
   * @example 404
   */
  status: number;
  /**
   * Optional human-readable explanation specific to this occurrence
   *
   * @example The requested resource was not found
   */
  detail?: string;
  /**
   * Optional OpenTelemetry trace ID associated with this request
   *
   * @example 132c7c05d8f744d596e15a2620cacfeb
   */
  instance?: string;
  /**
   * Optional dotted path identifying the request field related to the problem
   *
   * @example metadata.title
   */
  target?: string;
  /**
   * Present only when an upstream HTTP failure response exists.
   */
  upstream_response?: {
    /**
     * Original upstream HTTP status.
     *
     * @minimum 100
     * @maximum 599
     */
    status: number;
    /**
     * Original upstream failure body, treated as text.
     */
    body: string;
  };
};
